<script setup>
/* EXTRA CREDIT: Video link: (no video recorded) */
// Code Generated by AI: AI helped implement the components and check their behavior.
import { ref, computed } from "vue";
import AnimalCard from "./components/AnimalCard.vue";
import AnimalControls from "./components/AnimalControls.vue";

// App owns the source data; children only receive it and report user actions.
const animals = ref([]);
const loading = ref(false);
const error = ref("");
const activeFilter = ref("all");
const activeSort = ref("default");

async function loadAnimals() {
  loading.value = true;
  error.value = "";
  try {
    const response = await fetch("/animals.json");
    // HTTP failures still resolve fetch, so check the status before reading JSON.
    if (!response.ok) throw new Error(`Request failed with status ${response.status}`);
    animals.value = await response.json();
  } catch (err) {
    console.error(err);
    error.value = "Sorry, the animals couldn't be loaded. Try refreshing the page.";
  }
  loading.value = false;
}
loadAnimals();

function toggleAdoption(animal) {
  animal.adopted = !animal.adopted;
}

// This computed list and Vue's template updates replace updateDisplay().
// Vue tracks the animals, filter, and sort used here and recomputes when they
// change, so adopting or filtering never needs a separate redraw call.
const visibleAnimals = computed(() => {
  // Sorting a copy preserves the original order for the default option.
  let visible = animals.value.slice();
  if (activeFilter.value === "available") visible = visible.filter(a => !a.adopted);
  else if (activeFilter.value === "adopted") visible = visible.filter(a => a.adopted);
  if (activeSort.value === "name") visible.sort((a, b) => a.name.localeCompare(b.name));
  else if (activeSort.value === "age") visible.sort((a, b) => a.age - b.age);
  return visible;
});
// The count describes the whole shelter even when only some cards are visible.
const availableCount = computed(() => animals.value.filter(a => !a.adopted).length);
function setFilter(filter) { activeFilter.value = filter; }
function setSort(sort) { activeSort.value = sort; }
</script>

<template>
  <header>
    <h1>Animal Adoption Board</h1>
    <p>Meet the animals currently staying at our shelter.</p>
  </header>
  <main>
    <section aria-labelledby="animals-heading">
      <h2 id="animals-heading">Animals</h2>
      <p v-if="!loading && !error" id="animal-count">
        {{ availableCount }} of {{ animals.length }} animals are available for adoption.
      </p>
      <AnimalControls :active-filter="activeFilter" @filter="setFilter" @sort="setSort" />
      <div id="animal-list" aria-live="polite">
        <p v-if="loading">Loading animals...</p>
        <p v-else-if="error" class="error-message">{{ error }}</p>
        <p v-else-if="visibleAnimals.length === 0" class="empty-message">There are no animals to show.</p>
        <div v-else>
          <AnimalCard v-for="animal in visibleAnimals" :key="animal.id" :animal="animal"
            @toggle="toggleAdoption(animal)" />
        </div>
      </div>
    </section>
  </main>
</template>
